<?php get_header(); ?><main id="main" class="section content-area"><?php if (is_archive()) { the_archive_title('<h1>', '</h1>'); } elseif (is_search()) { ?><h1>Résultats pour « <?php echo esc_html(get_search_query()); ?> »</h1><?php } ?><?php if (have_posts()) : while (have_posts()) : the_post(); ?><article <?php post_class(); ?>><?php if (is_singular()) { the_title('<h1>', '</h1>'); the_content(); wp_link_pages(); } else { ?><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><?php the_excerpt(); } ?></article><?php endwhile; the_posts_pagination(); else : ?><h1>Aucun contenu trouvé</h1><p>Essayez une nouvelle recherche ou explorez nos collections.</p><?php get_search_form(); endif; ?></main><?php get_footer(); ?>
